CREATE FUNCTION public.read_conversation_citations(actor uuid, selected_conversation uuid, selected_messages uuid[])
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE conversation public.conversations; message public.messages;
    result jsonb := '{}'; cards jsonb; available boolean;
BEGIN
    IF COALESCE(auth.role(), '') <> 'service_role' OR actor IS NULL THEN
        RAISE EXCEPTION 'Trusted actor required' USING ERRCODE = '42501';
    END IF;
    SELECT * INTO conversation FROM public.conversations c
        WHERE c.conversation_id = selected_conversation AND c.user_id = actor;
    IF NOT FOUND THEN RAISE EXCEPTION 'Conversation not found' USING ERRCODE = 'P0002'; END IF;
    FOR message IN SELECT m.* FROM public.messages m WHERE m.conversation_id = selected_conversation
        AND m.message_type = 'assistant' AND m.message_id = ANY(selected_messages) ORDER BY m.message_sequence LOOP
        available := public.check_knowledge_policy(actor, message.knowledge_policy);
        IF conversation.chat_institution_id IS NOT NULL AND
            message.knowledge_policy->>'institution_id' IS DISTINCT FROM conversation.chat_institution_id::text THEN
            available := false;
        END IF;
        IF available AND conversation.knowledge_source_id IS NOT NULL AND (
            message.knowledge_policy->>'institution_id' IS DISTINCT FROM conversation.resource_institution_id::text
            OR message.knowledge_policy->'sources' IS NULL
            OR (SELECT array_agg(key) FROM jsonb_object_keys(message.knowledge_policy->'sources') key)
                IS DISTINCT FROM ARRAY[conversation.knowledge_source_id::text]
        ) THEN available := false; END IF;
        cards := '[]';
        IF available THEN
            SELECT COALESCE(jsonb_agg(card ORDER BY display_order, message_citation_id), '[]') INTO cards FROM (
                SELECT DISTINCT ON (citation.chunk_id) citation.display_order, citation.message_citation_id,
                    jsonb_build_object('chunk_id', chunk.chunk_id, 'quote', chunk.content_text,
                        'source_title', source.title, 'section', chunk.section_title,
                        'relevance_score', CASE WHEN retrieved.relevance_score BETWEEN 0 AND 1
                            THEN retrieved.relevance_score ELSE NULL END) AS card
                FROM public.message_citations citation
                JOIN public.retrieval_operations operation USING(retrieval_operation_id)
                JOIN public.ai_responses answer ON answer.ai_response_id = operation.ai_response_id
                    AND answer.message_id = citation.message_id
                JOIN public.retrieved_chunks retrieved ON retrieved.retrieval_operation_id = operation.retrieval_operation_id
                    AND retrieved.chunk_id = citation.chunk_id AND retrieved.selected_for_context
                JOIN public.knowledge_chunks chunk ON chunk.chunk_id = citation.chunk_id
                JOIN public.document_processing_runs run USING(processing_run_id)
                JOIN public.document_versions version USING(document_version_id)
                JOIN public.documents document USING(document_id)
                JOIN public.knowledge_sources source USING(knowledge_source_id)
                WHERE citation.message_id = message.message_id AND operation.status = 'completed'
                    AND run.status = 'ready' AND run.embedding_status = 'embedded' AND run.completed_at IS NOT NULL
                    AND source.institution_id::text = message.knowledge_policy->>'institution_id'
                    AND message.knowledge_policy->'sources' ? source.knowledge_source_id::text
                    AND message.knowledge_policy->'versions'->>version.document_version_id::text = source.knowledge_source_id::text
                    AND (source.published_revision_id IS NULL OR EXISTS (
                        SELECT 1 FROM public.knowledge_source_revision_documents manifest
                        WHERE manifest.revision_id = source.published_revision_id
                            AND manifest.document_version_id = version.document_version_id))
                ORDER BY citation.chunk_id, citation.display_order, citation.message_citation_id
            ) citations;
        END IF;
        result := result || jsonb_build_object(message.message_id::text,
            jsonb_build_object('available', available, 'sources', cards));
    END LOOP;
    RETURN result;
END;
$$;
